mapper.select:
SELECT

FROM EMAIL_RESERVATION
WHERE EMAIL_ID = #{emailId}
AND USER_ID = #{userId}

mapper.update:
UPDATE EMAIL_RESERVATION
SET STATUS = 'CANCELED',
UPDATED_AT = CURRENT_TIMESTAMP
WHERE EMAIL_ID = #{emailId}
AND USER_ID = #{userId}
AND STATUS = 'WAITING'

mapper.delete:
DELETE FROM EMAIL_RESERVATION
WHERE EMAIL_ID = #{emailId}
AND USER_ID = #{userId}
AND STATUS = 'CANCELED'
